pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Penalty for creating a "fragmented" bin (residual space too small to be useful for future items)
    // We define a fragment as a residual smaller than the smallest likely item (approx 10-20).
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powi(2) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it later
    let lookahead_penalty = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            0.0
        } else {
            (next_item_size as f64 - post) * 2.5
        }
    } else {
        0.0
    };

    // Dynamic thresholding: as we reach the end of the stream, prioritize filling existing bins
    // to minimize the total count, even if it creates slightly worse fragmentation.
    let end_game_weight = 1.0 - progress;

    // Base score: favor smaller post_residual (Best Fit logic)
    // We add a scaling factor based on the number of currently open bins to discourage 
    // unnecessary bin proliferation early in the stream.
    let mut score = post * (1.0 + (open_bins_count as f64 * 0.1));

    // Combine penalties
    score += fragmentation_penalty * (0.5 + 0.5 * end_game_weight);
    score += lookahead_penalty;

    // If this is a new bin candidate (bin_residual == bin_capacity), 
    // assign a baseline cost that discourages opening new bins unless the fit is truly optimal.
    if bin_residual == bin_capacity {
        // The cost of opening a new bin is high, but decreases as we exhaust existing options.
        // We normalize this by the average efficiency of current bins.
        score = (capacity * 0.6) + (mean_residual * 0.4);

        // If we have very few fitting bins, opening a new one might be more attractive later.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

