pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range (0, 10), it creates
    // a "sliver" that is likely unusable for future items (since min size is 10).
    // Heavily penalize this to force better fits.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0 + (10.0 - post_residual as f64) * 20.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty
    // proportional to the number of existing bins.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 1.5);
    }

    // 3. Lookahead Sensitivity: If the next item is large and the current placement
    // leaves little room, prioritize preserving space for the next item.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
        score += 50.0;
    }

    // 4. Efficiency Bias: Reward filling bins tightly (post_residual near 0).
    // If post_residual is 0, it is a perfect fit; give it a massive discount.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the item,
    // reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating a new bin:
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    // We penalize this heavily unless no other bin fits, or the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead optimization (2-step matching):
    // If there is a next item, we want the post_residual to be as close to next_item_size 
    // as possible without going under (avoiding waste).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect fit for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize creating a hole too small for the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Global distribution alignment:
    // Try to keep the bin residuals close to the global mean to maintain packing density.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 4. Scarcity avoidance:
    // If this is the only bin that can fit the item, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression scaling:
    // Towards the end of the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}
